import { test, expect } from '@playwright/test';

test.describe('Skip to Content Link', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page');
  });

  test('should display skip to content link and navigate to main content when clicked', async ({ page }) => {
    // Verify skip to content link is visible
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    await expect(skipLink).toBeVisible();

    // Verify main content is not visible initially
    const mainContent = page.locator('[data-testid="main-content"]');
    await expect(mainContent).not.toBeVisible();

    // Click the skip to content link
    await skipLink.click();

    // Verify main content is now visible
    await expect(mainContent).toBeVisible();

    // Verify page has scrolled to main content
    const mainContentBox = page.locator('[data-testid="main-content"]');
    const mainContentBoundingBox = await mainContentBox.boundingBox();
    expect(mainContentBoundingBox).not.toBeNull();
    expect(mainContentBoundingBox.y).toBeGreaterThan(0);
  });

  test('should not display skip to content link when on the homepage', async ({ page }) => {
    // Navigate to homepage
    await page.goto('/');

    // Verify skip to content link does not exist on homepage
    const skipLink = page.getByRole('link', { name: /skip to main content/i });
    await expect(skipLink).not.toBeVisible();

    // Verify main content is visible on homepage
    const mainContent = page.locator('[data-testid="main-content"]');
    await expect(mainContent).toBeVisible();
  });
});
